package offline;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
/** Format-only adapter: wire bytes remain opaque until ReceiveAudit. */
public final class Main {
    public static final class Event {public List<String> keys;public byte[] wire;public List<Long> auth;}
    public static final class Trace {
        public long connection,stream,bidi,uni,localBidi,localUni;public int cidLimit;
        public List<byte[]> localCids=new ArrayList<>();public byte[] peerCid,peerToken;
        public long[] received=new long[3];public List<Event> events=new ArrayList<>();
    }
    public static final class Packet {
        public String level;public long pn,truncated;public Long dcid,generation;
        public int offset,end,numberLength,phase;public byte[] destination,source,token,payload;
    }
    public static byte[] unhex(String s) {
        if(s.equals("-"))return new byte[0];byte[] b=new byte[s.length()/2];
        for(int i=0;i<b.length;i++)b[i]=(byte)((Character.digit(s.charAt(2*i),16)<<4)|Character.digit(s.charAt(2*i+1),16));return b;
    }
    public static String hex(byte[] b) {char[] h="0123456789abcdef".toCharArray(),s=new char[2*b.length];for(int i=0;i<b.length;i++){s[2*i]=h[(b[i]&255)>>>4];s[2*i+1]=h[b[i]&15];}return new String(s);}
    public static Map<String,Object> object(Object... f){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<f.length;i+=2)m.put((String)f[i],f[i+1]);return m;}
    public static String json(Object v){
        if(v==null)return "null";if(v instanceof Number||v instanceof Boolean)return v.toString();
        if(v instanceof Map){StringJoiner j=new StringJoiner(",","{","}");for(Object x:((Map<?,?>)v).entrySet()){Map.Entry<?,?> e=(Map.Entry<?,?>)x;j.add(json(e.getKey())+":"+json(e.getValue()));}return j.toString();}
        if(v instanceof Iterable){StringJoiner j=new StringJoiner(",","[","]");for(Object x:(Iterable<?>)v)j.add(json(x));return j.toString();}
        String s=v.toString();StringBuilder b=new StringBuilder("\"");for(int i=0;i<s.length();i++){char c=s.charAt(i);if(c=='"'||c=='\\')b.append('\\').append(c);else if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);}return b.append('"').toString();
    }
    public static void main(String[] args)throws Exception{
        BufferedReader in=new BufferedReader(new InputStreamReader(System.in,StandardCharsets.UTF_8));List<Object> out=new ArrayList<>();int count=Integer.parseInt(in.readLine());
        for(int i=0;i<count;i++){
            Trace t=new Trace();String[] h=in.readLine().split(" ");t.connection=Long.parseLong(h[0]);t.stream=Long.parseLong(h[1]);t.bidi=Long.parseLong(h[2]);t.uni=Long.parseLong(h[3]);t.cidLimit=Integer.parseInt(h[4]);t.localBidi=Long.parseLong(h[5]);t.localUni=Long.parseLong(h[6]);
            for(String cid:in.readLine().split(" "))t.localCids.add(unhex(cid));String[] peer=in.readLine().split(" ");t.peerCid=unhex(peer[0]);t.peerToken=unhex(peer[1]);
            String[] seeds=in.readLine().split(" ");for(int j=0;j<3;j++)t.received[j]=seeds[j].equals("-")?-1:Long.parseLong(seeds[j]);
            int events=Integer.parseInt(in.readLine());for(int j=0;j<events;j++){
                String[] e=in.readLine().split(" ");Event event=new Event();t.events.add(event);
                if(e[0].equals("K")){event.keys=new ArrayList<>();for(int k=1;k<e.length;k++)event.keys.add(e[k]);}
                else{event.wire=unhex(e[1]);event.auth=new ArrayList<>();String line=in.readLine();if(!line.equals("-"))for(String value:line.split(" "))event.auth.add(value.equals("-")?null:Long.valueOf(value));}
            }
            out.add(new ReceiveAudit().audit(t));
        }
        System.out.println(json(object("traces",out)));
    }
}
